#!/usr/bin/env python3
"""Assemble the bare-metal gemmini matmul kernel (gsim_gemmini_bootrom.S) and emit
a C header (`gemmini_bootrom.h`) holding the BootROM word image for the GSIM
gemmini M3 full-SoC harness to bake into ChipTop's `bootrom$rom[]` array.

The ChipTop BootROM is a 512x64-bit combinational `wire rom` mapped at 0x10000
(read path: index = address[11:3]; GSIM_ENGINE.md 5).  GSIM lowers it to the
public member array `system$bootrom_domain$bootrom$rom[512]`, initialised ONCE in
an event-gated block, so a harness overwrite persists.  Word i holds the 8 bytes
at 0x10000 + 8*i, little-endian: rom[i][31:0] = insn at 0x10000+8i, [63:32] =
insn at 0x10000+8i+4.

No regex (repo rule): pure toolchain + struct byte packing.

Usage:  gsim_gemmini_bootrom_bake.py <out_dir> [--rv-bin <path-to-riscv-bin>]
        writes <out_dir>/gemmini_bootrom.h
"""
import os
import struct
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ASM = os.path.join(HERE, "gsim_gemmini_bootrom.S")
DEFAULT_RV_BIN = "/scratch/agustin/projects/riscv-gcc14/riscv/bin"
# The link address this script CHOOSES and passes to `ld -Ttext=` below; it is a parameter of this
# build, not a fact read off any target, so there is nothing to derive it from. Overridable so the
# choice is explicit rather than buried.
# derived-ok: link address set by this script and handed to ld -Ttext (not an ISA encoding)
TEXT_BASE = int(os.environ.get("GSIM_BOOTROM_TEXT_BASE", "0x10000"), 0)


def _tool(rv_bin, name):
    return os.path.join(rv_bin, "riscv64-unknown-elf-" + name)


def assemble(out_dir, rv_bin):
    obj = os.path.join(out_dir, "gemmini_bootrom.o")
    elf = os.path.join(out_dir, "gemmini_bootrom.elf")
    binf = os.path.join(out_dir, "gemmini_bootrom.bin")
    subprocess.run([_tool(rv_bin, "as"), "-march=rv64gc", "-mabi=lp64",
                    ASM, "-o", obj], check=True)
    subprocess.run([_tool(rv_bin, "ld"), "-Ttext=0x%x" % TEXT_BASE, "-e", "_start",
                    "-nostdlib", obj, "-o", elf], check=True)
    subprocess.run([_tool(rv_bin, "objcopy"), "-O", "binary", elf, binf], check=True)
    with open(binf, "rb") as f:
        raw = f.read()
    # pad to a multiple of 8 bytes so every word is complete
    if len(raw) % 8:
        raw = raw + b"\x00" * (8 - (len(raw) % 8))
    words = [struct.unpack_from("<Q", raw, i)[0] for i in range(0, len(raw), 8)]
    return words, elf


def emit_header(out_dir, rv_bin):
    words, elf = assemble(out_dir, rv_bin)
    lines = []
    lines.append("// AUTO-GENERATED by gsim_gemmini_bootrom_bake.py -- do not edit.")
    lines.append("// Bare-metal gemmini matmul kernel baked into ChipTop bootrom$rom[] (base 0x%x)." % TEXT_BASE)  # target-ok: a per-target model-build helper; this target IS its subject
    lines.append("#pragma once")
    lines.append("#include <cstdint>")
    lines.append("static const int GEMMINI_BOOTROM_NWORDS = %d;" % len(words))
    lines.append("static const uint64_t GEMMINI_BOOTROM_WORDS[%d] = {" % len(words))
    for i, w in enumerate(words):
        lines.append("  0x%016xull, // rom[%d] @ 0x%x" % (w, i, TEXT_BASE + 8 * i))
    lines.append("};")
    text = "\n".join(lines) + "\n"
    path = os.path.join(out_dir, "gemmini_bootrom.h")
    with open(path, "w") as f:
        f.write(text)
    print("wrote %s (%d rom words, %d bytes) from %s" %
          (path, len(words), len(words) * 8, elf))
    for i, w in enumerate(words):
        print("  rom[%2d] @ 0x%05x = 0x%016x" % (i, TEXT_BASE + 8 * i, w))


if __name__ == "__main__":
    args = sys.argv[1:]
    rv_bin = DEFAULT_RV_BIN
    if "--rv-bin" in args:
        k = args.index("--rv-bin")
        rv_bin = args[k + 1]
        del args[k:k + 2]
    if len(args) != 1:
        print(__doc__)
        sys.exit(2)
    emit_header(args[0], rv_bin)
